SELECT CASE WHEN ("__policysql_t0"."name" = :chosen) THEN CAST ("__policysql_t0"."name" AS TEXT) ELSE ("__policysql_t0"."name" || :suffix) END AS "label" FROM "projects" AS "__policysql_t0" WHERE ("__policysql_t0"."tenant_id" = :__policysql_session_tenant_id) ORDER BY "__policysql_t0"."name" ASC LIMIT 2
